/* Only the three entry points an OFX host looks up are exported. Everything else stays
   local, so the plugin can never interpose on symbols in the host process.

   This matters more here than it does for a plain image effect. The plugin privately loads
   ONNX Runtime and its dependency tree under RTLD_LOCAL rather than linking it; this map
   keeps every symbol compiled into the OFX module itself out of the host's global scope.
   Both boundaries matter when Flame already carries other versions of the same libraries. */
{
  global:
    OfxGetNumberOfPlugins;
    OfxGetPlugin;
    OfxSetHost;
  local:
    *;
};
